"""Tool Router for Computer Use Integration.

Architecture:
Qwen (Mind)
  ↓
Tool Router (Policy, Validation, Routing)
  ↓
Laya (Eyes & Hands)
"""

from __future__ import annotations

import logging
from typing import Any, Dict, List, Optional
from pydantic import BaseModel, Field

from alpha.computer_use.laya import LayaComputerInterface, LayaObservationResult
from alpha.computer_use.permissions import ComputerActionType, ApprovalToken

logger = logging.getLogger("alpha.computer_use.router")


class CognitiveActionIntent(BaseModel):
    """Action intent generated by Qwen Foundation Model."""
    action_type: str  # "READ", "OBSERVE", "NAVIGATE", "INSPECT", "BROWSE", "DESKTOP_INSPECT", "EXECUTE", "WRITE", "COMPUTER_TASK"
    target: str
    content: Optional[str] = None
    rationale: str = ""
    approval_token: Optional[ApprovalToken] = None


class LayaToolRouter:
    """Routes cognitive intents from Qwen into concrete actions on Laya."""

    def __init__(self, laya: Optional[LayaComputerInterface] = None):
        self.laya = laya or LayaComputerInterface()

    def route_action(self, intent: CognitiveActionIntent) -> LayaObservationResult:
        """Validates and executes cognitive intent through Laya."""
        act = intent.action_type.upper()
        logger.info(f"LayaToolRouter routing intent {act} on target '{intent.target}'")

        if act == "READ":
            return self.laya.read_file(intent.target)
        elif act == "OBSERVE":
            return self.laya.observe_system_state()
        elif act == "INSPECT":
            return self.laya.inspect_ast(intent.target)
        elif act == "NAVIGATE":
            return self.laya.navigate_directory(intent.target)
        elif act == "BROWSE":
            return self.laya.observe_browser(intent.target)
        elif act == "DESKTOP_INSPECT":
            return self.laya.observe_desktop(intent.target)
        elif act == "GIT_DIFF":
            return self.laya.inspect_git_diff()
        elif act == "EXECUTE":
            return self.laya.execute_command(intent.target, approval_token=intent.approval_token)
        elif act == "WRITE":
            return self.laya.write_file(intent.target, intent.content or "", approval_token=intent.approval_token)
        elif act == "COMPUTER_TASK":
            start_url = intent.target if intent.target.startswith("http") else ""
            goal = intent.rationale or intent.target
            return self.laya.execute_computer_task(
                goal=goal,
                start_url=start_url,
                approval_token=intent.approval_token
            )
        else:
            return LayaObservationResult(
                action=act,
                target=intent.target,
                success=False,
                data={"error": f"Unknown action type: {act}"},
                latency_ms=0.0
            )
